const now = new Date();
const local = new Date(now.toLocaleString('en-US', { timeZone: 'America/La_Paz' }));
const day = local.getDay();
const daysSinceMonday = (day + 6) % 7;
const currentMonday = new Date(local);
currentMonday.setDate(local.getDate() - daysSinceMonday);
currentMonday.setHours(0, 0, 0, 0);
const start = new Date(currentMonday);
start.setDate(currentMonday.getDate() - 7);
const end = new Date(currentMonday);
end.setDate(currentMonday.getDate() - 1);
const fmt = (date) => date.toISOString().slice(0, 10);
return [{
  json: {
    period: `semana_${fmt(start)}`,
    period_start: fmt(start),
    period_end: fmt(end),
  },
}];

const data = $input.first().json;
const period = 'semana_' + data.period_start;
const trim = (value, depth = 0) => {
  if (Array.isArray(value)) return value.slice(0, 8).map((entry) => trim(entry, depth + 1));
  if (value && typeof value === 'object' && depth < 4) {
    return Object.fromEntries(Object.entries(value).map(([key, entry]) => [key, trim(entry, depth + 1)]));
  }
  return value;
};
const sourceData = trim({
  period,
  period_start: data.period_start,
  period_end: data.period_end,
  facturacion_total: data.facturacion_total,
  utilidad_bruta: data.utilidad_bruta,
  utilidad_disponible: data.utilidad_disponible,
  margen_global_pct: data.margen_global_pct,
  crecimiento_mensual_pct: data.crecimiento_mensual_pct,
  categoria_mas_rentable: data.categoria_mas_rentable,
  resumen_categorias: data.resumen_categorias,
  mix_ventas_categorias: data.mix_ventas_categorias,
  kpis_comerciales: data.kpis_comerciales,
  top_productos_rentables: data.top_productos_rentables,
  top_productos_mayor_rotacion: data.top_productos_mayor_rotacion,
  analisis_celulares: data.analisis_celulares,
  analisis_computadoras: data.analisis_computadoras,
  analisis_accesorios: data.analisis_accesorios,
  analisis_productos_apple: data.analisis_productos_apple,
  analisis_servicios_tecnicos: data.analisis_servicios_tecnicos,
});
const system = 'Eres analista comercial senior para AppleBoss. Responde SOLO JSON valido, sin markdown. Usa espanol claro, breve y accionable. No inventes cifras: conserva los valores numericos del JSON recibido.';
const schema = [
  'Genera un informe inteligente semanal para AppleBoss con esta estructura exacta:',
  '{',
  '  "period_start":"' + data.period_start + '",',
  '  "period_end":"' + data.period_end + '",',
  '  "resumen_ejecutivo":{"descripcion":"texto breve","facturacion_total":0,"utilidad_total":0,"utilidad_disponible":0,"margen_global_pct":0,"crecimiento_mensual_pct":0},',
  '  "analisis_por_categoria":[{"categoria":"texto","ingresos":0,"utilidad":0,"margen_promedio_pct":0,"ticket_promedio":0,"nivel_riesgo":"BAJO|MEDIO|ALTO","observacion":"texto"}],',
  '  "analisis_celulares":{},',
  '  "analisis_computadoras":{},',
  '  "analisis_accesorios":{},',
  '  "riesgos_estrategicos":[{"tipo":"texto","descripcion":"texto","impacto":"texto"}],',
  '  "oportunidades":[{"descripcion":"texto","impacto_estimado":"texto"}],',
  '  "recomendaciones_ejecutivas":[{"accion":"texto","prioridad":"ALTA|MEDIA|BAJA"}],',
  '  "productos_destacados":[{"producto":"texto","categoria":"texto","unidades":0,"ingresos":0,"utilidad":0,"margen_pct":0}],',
  '  "datos_base":{}',
  '}',
  '',
  'Reglas:',
  '- Mantén facturacion_total=' + Number(data.facturacion_total || 0) + ', utilidad_total=' + Number(data.utilidad_bruta || 0) + ', utilidad_disponible=' + Number(data.utilidad_disponible || 0) + ' y margen_global_pct=' + Number(data.margen_global_pct || 0) + '.',
  '- Usa maximo 5 items por lista.',
  '- Si no hay datos suficientes en una seccion, devuelve lista vacia o texto Sin registro suficiente.',
  '- Las recomendaciones deben ser concretas para inventario, precios, margen, descuentos o reposicion.',
  '',
  'Datos comerciales: ' + JSON.stringify(sourceData)
].join('\n');
return [{
  json: {
    period,
    period_start: data.period_start,
    period_end: data.period_end,
    sourceData,
    openaiRequest: {
      model: 'gpt-4o-mini',
      temperature: 0.2,
      max_tokens: 1800,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: schema }
      ]
    }
  }
}];

const response = $input.first().json;
const context = $node['Preparar prompt ChatGPT'].json;
let content = response?.choices?.[0]?.message?.content;
if (Array.isArray(content)) {
  content = content.map((part) => part?.text || part?.content || '').join('');
}
if (typeof content !== 'string' || !content.trim()) {
  throw new Error('ChatGPT no devolvio contenido para el informe');
}
let report;
try {
  report = JSON.parse(content);
} catch (error) {
  throw new Error('ChatGPT devolvio JSON invalido: ' + error.message);
}
const source = context.sourceData || {};
const num = (value) => Number(value ?? 0);
report.period_start = context.period_start;
report.period_end = context.period_end;
report.datos_base = source;
report.resumen_ejecutivo = report.resumen_ejecutivo || {};
report.resumen_ejecutivo.facturacion_total = num(source.facturacion_total);
report.resumen_ejecutivo.utilidad_total = num(source.utilidad_bruta);
report.resumen_ejecutivo.utilidad_disponible = num(source.utilidad_disponible);
report.resumen_ejecutivo.margen_global_pct = num(source.margen_global_pct);
report.resumen_ejecutivo.crecimiento_mensual_pct = num(source.crecimiento_mensual_pct);
if (!report.resumen_ejecutivo.descripcion) {
  report.resumen_ejecutivo.descripcion = 'Reporte del ' + context.period_start + ' al ' + context.period_end + '. Facturacion Bs ' + num(source.facturacion_total).toFixed(2) + ', utilidad Bs ' + num(source.utilidad_bruta).toFixed(2) + ' y margen ' + num(source.margen_global_pct).toFixed(2) + '%.';
}
if (!Array.isArray(report.analisis_por_categoria)) {
  report.analisis_por_categoria = [];
}
if (report.analisis_por_categoria.length === 0 && Array.isArray(source.resumen_categorias)) {
  report.analisis_por_categoria = source.resumen_categorias.slice(0, 5).map((item) => ({
    categoria: item.categoria || 'sin_categoria',
    ingresos: num(item.ingresos),
    utilidad: num(item.utilidad),
    margen_promedio_pct: num(item.margen_pct),
    ticket_promedio: 0,
    nivel_riesgo: num(item.margen_pct) < 10 ? 'MEDIO' : 'BAJO',
    observacion: 'Categoria incluida por datos comerciales.'
  }));
}
report.analisis_celulares = report.analisis_celulares || source.analisis_celulares || {};
report.analisis_computadoras = report.analisis_computadoras || source.analisis_computadoras || {};
report.analisis_accesorios = report.analisis_accesorios || source.analisis_accesorios || {};
report.riesgos_estrategicos = Array.isArray(report.riesgos_estrategicos) ? report.riesgos_estrategicos.slice(0, 5) : [];
report.oportunidades = Array.isArray(report.oportunidades) ? report.oportunidades.slice(0, 5) : [];
report.recomendaciones_ejecutivas = Array.isArray(report.recomendaciones_ejecutivas) ? report.recomendaciones_ejecutivas.slice(0, 5) : [];
report.productos_destacados = Array.isArray(report.productos_destacados) ? report.productos_destacados.slice(0, 5) : (source.top_productos_rentables || []).slice(0, 5);
return [{
  json: {
    laravelPayload: {
      period: context.period,
      period_start: context.period_start,
      period_end: context.period_end,
      report,
      engine: response.model || context.openaiRequest?.model || 'gpt-4o-mini',
      prompt_version: 'retail_v2_chatgpt_json'
    },
    openaiUsage: response.usage || null
  }
}];
